'use strict';
const $=id=>document.getElementById(id);
const OPS={add:['＋','たしざん'],sub:['−','ひきざん'],mul:['×','かけざん'],div:['÷','わりざん']};
const LEVELS=['かんたん','ふつう','むずかしい'];
const BANK={
add:[[[12,6],[23,14],[41,25],[32,17]],[[27,15],[46,28],[58,17],[36,49]],[[268,157],[476,285],[638,194],[759,168]]],
sub:[[[18,5],[47,23],[65,31],[39,16]],[[52,28],[73,46],[61,35],[84,57]],[[302,178],[500,263],[704,386],[603,257]]],
mul:[[[2,3],[4,2],[3,5],[5,5]],[[23,4],[36,3],[47,6],[58,7]],[[23,14],[36,25],[47,32],[68,24]]],
div:[[[12,3],[20,4],[18,2],[24,6]],[[72,3],[84,4],[96,6],[65,5]],[[83,4],[97,6],[125,8],[158,7]]]
};
const DESCRIPTIONS={add:['くりあがり なし','くりあがり あり','3けた・くりあがり あり'],sub:['くりさがり なし','くりさがり あり','3けた・0から くりさがり'],mul:['くくで ちょうせん','2けた × 1けた','2けた × 2けた'],div:['くくで われるよ','2けた ÷ 1けた','あまりの ある わりざん']};
const KEY='hissan-handwriting-preview-v1';
let storageOK=true;
function readProgress(){try{const v=JSON.parse(localStorage.getItem(KEY))||{};return {rounds:Number.isSafeInteger(v.rounds)&&v.rounds>=0?v.rounds:0,badges:Array.isArray(v.badges)?v.badges.filter(x=>OPS[x]):[]};}catch{storageOK=false;return {rounds:0,badges:[]};}}
let progress=readProgress(),config={op:'add',level:0},session=null,screen='setup',inkVersion=0,activeInk=null;
function saveProgress(){try{localStorage.setItem(KEY,JSON.stringify(progress));}catch{storageOK=false;}}
function setStatus(text){$('notice').textContent=text;}
function picture(stage,large=false){return `<div class="reveal-picture ${large?'large':''}" role="img" aria-label="ふしぎなしまの え。4つのうち ${stage}つ できた"><img class="underpainting" src="../assets/reward-island.jpg" alt="">${[0,1,2,3].map(i=>`<div class="picture-part part-${i} ${i<stage?'revealed':''}">${i<stage?'<img src="../assets/reward-island.jpg" alt="">':'<span>？</span>'}</div>`).join('')}</div>`;}
function render(focus=true){inkVersion++;activeInk=null;$('notice').textContent='';$('owned-count').textContent=Math.floor(progress.rounds/4);$('challenge-tab').setAttribute('aria-pressed',screen!=='album');$('album-tab').setAttribute('aria-pressed',screen==='album');if(screen==='setup')setup();else if(screen==='quiz')quiz();else if(screen==='reward')reward();else album();if(!storageOK)$('screen').insertAdjacentHTML('beforeend','<p class="storage-note">このブラウザでは えほんを ほぞんできないよ。ページを とじると もとに もどるよ。</p>');if(focus){$('screen').focus({preventScroll:true});window.scrollTo(0,0);}}
function setup(){const [a,b]=BANK[config.op][config.level][0];const stage=progress.rounds%4;$('screen').innerHTML=`<section class="book"><div class="hero"><p class="eyebrow">ペンでも ゆびでも かけるよ</p><h1>ノートに かいてみよう</h1><p class="sub">3もん できると、えが すこしずつ できるよ。</p><img src="../assets/pencil-sticker.png" alt=""></div><div class="setup-grid"><section class="section"><h2><span class="number">1</span>けいさんを えらぼう</h2><div class="choices">${Object.entries(OPS).map(([op,v])=>`<button data-op="${op}" class="choice" aria-pressed="${op===config.op}"><b>${v[0]}</b>${v[1]}</button>`).join('')}</div></section><section class="section blue"><h2><span class="number">2</span>むずかしさは？</h2><div class="levels">${LEVELS.map((v,i)=>`<button data-level="${i}" aria-pressed="${i===config.level}">${v}</button>`).join('')}</div><p class="example">${DESCRIPTIONS[config.op][config.level]}<strong>たとえば ${a} ${OPS[config.op][0]} ${b}</strong></p></section></div><section class="picture-preview"><div><p class="eyebrow">ごほうびの え</p><h2>ふしぎな しまの ピクニック</h2><p class="sub">3もんで ひとつ、12もんで かんせい！</p><p class="picture-count">${stage} / 4 できた</p></div>${picture(stage)}</section><button id="start" class="primary start">ペンで 3もんに ちょうせん →</button><p class="promise">よみとった すうじは、さいてんの まえに たしかめるよ。</p></section>`;
document.querySelectorAll('[data-op]').forEach(b=>b.onclick=()=>{config.op=b.dataset.op;render(false);});document.querySelectorAll('[data-level]').forEach(b=>b.onclick=()=>{config.level=Number(b.dataset.level);render(false);});$('start').onclick=()=>{const pool=[...BANK[config.op][config.level]];for(let i=pool.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[pool[i],pool[j]]=[pool[j],pool[i]];}session={...config,index:0,claimed:false,questions:pool.slice(0,3).map(([a,b])=>({a,b,cells:{answer:[[],[],[],[]],remainder:[[],[]]},answer:'',remainder:'',phase:'write',hint:false,history:[],candidates:{},confirmedVersion:null,revision:0}))};screen='quiz';render();};}
function question(){return session.questions[session.index];}
function solution(q){return session.op==='add'?q.a+q.b:session.op==='sub'?q.a-q.b:session.op==='mul'?q.a*q.b:Math.floor(q.a/q.b);}
function needsRemainder(){return session.op==='div'&&session.level===2;}
function cellStrip(q,field,label){return `<section class="ink-field"><h2>${label}</h2><div class="ink-strip ${field==='remainder'?'short':''}">${q.cells[field].map((_,i)=>`<div class="ink-cell"><span class="cell-index" aria-hidden="true">${i+1}</span><canvas width="112" height="152" data-field="${field}" data-cell="${i}" aria-label="${label}の ${i+1}ばんめの マス。ペンか ゆびで すうじを かいてね"></canvas></div>`).join('')}</div></section>`;}
function quiz(){const q=question(),review=q.phase==='review',done=q.phase==='done';$('screen').innerHTML=`<section class="book ink-book"><div class="row"><div><p class="eyebrow">${LEVELS[session.level]}・${OPS[session.op][1]}</p><h1>${q.a} ${OPS[session.op][0]} ${q.b} ＝ ？</h1></div><button id="leave">← えらびなおす</button></div><div class="progress">${session.questions.map((p,i)=>`<span class="${i===session.index?'now':p.phase==='done'?'done':''}">${p.phase==='done'?'✓ ':''}${i+1}もんめ</span>`).join('')}</div><div class="ink-instruction"><strong>${done?'よく がんばったね！':review?'② よみとった すうじを たしかめよう':'① こたえを ペンで かこう'}</strong><p>${done?'てがきの こたえも のこっているよ。':review?'かいた すうじと おなじかな？ ちがったら なおしてね。':'ひとマスに すうじを ひとつ。ひだりから かいてね。'}</p></div><div class="writing-paper">${cellStrip(q,'answer','こたえ')}${needsRemainder()?cellStrip(q,'remainder','あまり'):''}</div><div class="ink-tools"><button id="undo" ${done?'disabled':''}>ひとつ もどす</button><button id="clear" ${done?'disabled':''}>かきなおす</button><button id="hint">💡 ヒント</button>${q.phase==='write'?'<button id="manual">よめないとき</button>':''}</div><p id="hint-box" class="feedback" ${q.hint?'':'hidden'}>${hint(q)}</p><div id="recognition-error" role="status"></div>${review?reviewPanel(q):''}${done?`<div class="feedback good" role="status">はなまる！ できたね 🌸</div>`:''}<div id="grade-message" role="status"></div><div class="ink-actions">${q.phase==='write'?'<button class="primary" id="read-ink">かいた すうじを よみとる →</button>':review?'<button id="back-write">← てがきを なおす</button><button class="primary" id="grade">この すうじで さいてん</button>':'<button id="reopen">よみとりを なおす</button>'}</div><p class="promise">よみとりが ちがっても だいじょうぶ。なんどでも なおせるよ。</p><div class="controls"><button id="prev" ${session.index===0?'disabled':''}>← まえへ</button><button class="primary" id="next" ${done?'':'disabled'}>${session.index===2?'えを みる →':'つぎへ →'}</button></div></section>`;
attachCanvases(q);if($('manual'))$('manual').onclick=()=>{q.manual=true;q.answer='';q.remainder='';q.phase='review';q.confirmedVersion=null;render(false);$('review-answer').focus({preventScroll:true});$('review-panel').scrollIntoView({block:'nearest',behavior:'smooth'});};$('leave').onclick=()=>{screen='setup';render();};$('prev').onclick=()=>{session.index--;render();};$('next').onclick=()=>{if(q.phase!=='done')return;if(session.index<2){session.index++;render();}else{claim();screen='reward';render();}};$('undo').onclick=()=>{const last=q.history.pop();if(last)q.cells[last.field][last.index].pop();invalidate(q);render(false);};$('clear').onclick=()=>{q.cells={answer:[[],[],[],[]],remainder:[[],[]]};q.history=[];invalidate(q);render(false);};$('hint').onclick=()=>{q.hint=!q.hint;$('hint-box').hidden=!q.hint;};if($('read-ink'))$('read-ink').onclick=readInk;if($('back-write'))$('back-write').onclick=()=>{invalidate(q);render(false);};if($('reopen'))$('reopen').onclick=()=>{q.phase='review';q.confirmedVersion=null;render(false);};if($('grade')){$('grade').onclick=grade;for(const field of ['answer',...(needsRemainder()?['remainder']:[])]){$('review-'+field).oninput=()=>{q[field]=$('review-'+field).value.replace(/[^0-9]/g,'').slice(0,field==='answer'?4:2);$('review-'+field).value=q[field];q.confirmedVersion=null;$('grade-message').textContent='';};}}
}
function invalidate(q){q.revision++;q.phase='write';q.confirmedVersion=null;q.answer='';q.remainder='';q.candidates={};}
function drawCell(canvas,strokes){const ctx=canvas.getContext('2d');ctx.clearRect(0,0,112,152);ctx.strokeStyle='#60414b';ctx.lineWidth=4;ctx.lineCap='round';ctx.lineJoin='round';for(const stroke of strokes){if(!stroke.length)continue;ctx.beginPath();ctx.moveTo(...stroke[0]);for(const p of stroke.slice(1))ctx.lineTo(...p);ctx.stroke();}}
function attachCanvases(q){document.querySelectorAll('canvas[data-cell]').forEach(canvas=>{const field=canvas.dataset.field,index=Number(canvas.dataset.cell);drawCell(canvas,q.cells[field][index]);let pending=null,pointer=null,epoch=inkVersion;
const point=e=>{const r=canvas.getBoundingClientRect();return [Math.max(0,Math.min(112,(e.clientX-r.left)*112/r.width)),Math.max(0,Math.min(152,(e.clientY-r.top)*152/r.height))];};
canvas.onpointerdown=e=>{if(q.phase!=='write'||activeInk||e.button>0)return;e.preventDefault();pointer=e.pointerId;activeInk={canvas,pointer};pending=[point(e)];canvas.setPointerCapture(pointer);canvas.parentElement.classList.add('active');};
canvas.onpointermove=e=>{if(e.pointerId!==pointer||!pending||epoch!==inkVersion)return;e.preventDefault();const events=e.getCoalescedEvents?.()||[e];for(const v of events){const p=point(v);if(Math.hypot(p[0]-pending[pending.length-1][0],p[1]-pending[pending.length-1][1])>.5)pending.push(p);}drawCell(canvas,[...q.cells[field][index],pending]);};
const finish=(e,cancelled)=>{if(e.pointerId!==pointer)return;const pts=pending;pending=null;activeInk=null;pointer=null;canvas.parentElement.classList.remove('active');if(canvas.hasPointerCapture(e.pointerId))canvas.releasePointerCapture(e.pointerId);if(!cancelled&&pts&&pts.length>1&&epoch===inkVersion){q.cells[field][index].push(pts);q.history.push({field,index});q.revision++;q.confirmedVersion=null;}drawCell(canvas,q.cells[field][index]);};
canvas.onpointerup=e=>finish(e,false);canvas.onpointercancel=e=>finish(e,true);canvas.onlostpointercapture=e=>{if(pointer===e.pointerId)finish(e,true);};canvas.oncontextmenu=e=>e.preventDefault();});}
function readInk(){const q=question();if(activeInk){$('recognition-error').textContent='ペンを はなしてから おしてね。';return;}const fields=['answer',...(needsRemainder()?['remainder']:[])];const readings={};const candidates={};for(const field of fields){const cells=q.cells[field],filled=cells.map((s,i)=>s.length?i:-1).filter(i=>i>=0);if(!filled.length){$('recognition-error').textContent=field==='answer'?'こたえの マスに すうじを かいてね。':'あまりの マスにも かいてね。0でも かいてね。';return;}const first=filled[0],last=filled[filled.length-1];if(last-first+1!==filled.length){$('recognition-error').textContent='すうじの あいだの あきマスを うめてね。';return;}const digits=[];candidates[field]=[];for(const i of filled){const results=DigitReader.recognize(cells[i]);if(!results.length||results[0].distance>.18){$('recognition-error').textContent='うまく よめなかったよ。「かきなおす」で、すうじを おおきく かいてみてね。';return;}digits.push(results[0].digit);candidates[field].push(results);}readings[field]=digits.join('');}
q.manual=false;q.answer=readings.answer;q.remainder=readings.remainder||'';q.candidates=candidates;q.phase='review';q.confirmedVersion=null;render(false);$('review-answer').focus({preventScroll:true});$('review-panel').scrollIntoView({block:'nearest',behavior:'smooth'});}
function reviewPanel(q){return `<section class="review-panel" id="review-panel"><h2>${q.manual?'かいた すうじを おしえてね':'「この すうじ」って かいたかな？'}</h2><p class="sub">${q.manual?'うまく よめないときは、すうじで つたえられるよ。':'まだ さいてん していないよ。てがきと くらべてね。'}</p><div class="answer-fields">${['answer',...(needsRemainder()?['remainder']:[])].map(field=>`<label>${field==='answer'?'こたえ':'あまり'}<input id="review-${field}" inputmode="numeric" autocomplete="off" maxlength="${field==='answer'?4:2}" value="${q[field]}" aria-label="よみとった ${field==='answer'?'こたえ':'あまり'}"></label>`).join('')}</div><p class="muted">ちがう すうじは、ここを おして なおせるよ。<br>なおしても ごほうびは へらないよ。</p></section>`;}
function grade(){const q=question();if(q.phase!=='review'||activeInk)return;if(!/^\d{1,4}$/.test(q.answer)||(needsRemainder()&&!/^\d{1,2}$/.test(q.remainder))){$('grade-message').textContent='よみとった すうじを たしかめてね。';return;}q.confirmedVersion=q.revision;if(Number(q.answer)===solution(q)&&(!needsRemainder()||Number(q.remainder)===q.a%q.b)){q.phase='done';render(false);}else{$('grade-message').innerHTML='<div class="feedback">もういちど たしかめよう。<br>よみとりが ちがう？ うえの すうじを なおせるよ。<br>けいさんを やりなおす？ 「てがきを なおす」で もどれるよ。</div>';}}
function hint(q){const a=solution(q);return session.op==='div'?`${q.b} × □ が ${q.a}を こえないように かんがえよう。<br>こたえは ${a}${needsRemainder()?'、あまり '+q.a%q.b:''}。たしかめて かいてみよう。`:`いちのくらいから かんがえよう。<br>${q.a} ${OPS[session.op][0]} ${q.b} ＝ ${a}。たしかめて かいてみよう。`;}
function claim(){if(session.claimed||!session.questions.every(q=>q.phase==='done'))return;session.claimed=true;progress.rounds++;if(!progress.badges.includes(session.op))progress.badges.push(session.op);saveProgress();}
function reward(){const stage=(progress.rounds-1)%4+1;$('screen').innerHTML=`<section class="book reward"><p class="eyebrow">3もん がんばったね！</p><h1>${stage===4?'えが かんせいしたよ！':'えが すこし できたよ！'}</h1><p class="sub">ふしぎな しまの ピクニック</p>${picture(stage,true)}<p class="picture-count">${stage} / 4 できた ${stage===4?'🌸':'・あと '+(4-stage)+'かいで かんせい！'}</p><div class="controls"><button id="again">もう3もん あそぶ</button><button class="primary" id="open-album">できたえほん →</button></div></section>`;$('again').onclick=()=>{session=null;screen='setup';render();};$('open-album').onclick=()=>{screen='album';render();};}
function album(){const completed=Math.floor(progress.rounds/4),stage=progress.rounds%4;$('screen').innerHTML=`<section class="book"><p class="eyebrow">あそんだ きろく</p><h1>わたしの できたえほん</h1><p class="sub">3もんずつ、じぶんの ペースで そだてよう。</p><h2 class="album-heading">${completed?'かんせいした え':'いま つくっている え'}</h2>${picture(completed?4:stage,true)}<p class="picture-count">${completed?'かんせい '+completed+'かい！':'4つのうち '+stage+'つ できた'}</p>${completed?'<p class="sub">つぎの 1まい：'+stage+' / 4 できた</p>':''}<p class="badge">${progress.badges.length?'🏅 '+progress.badges.map(op=>OPS[op][1]+'に ちょうせん').join(' ・ '):'3もんに ちょうせんすると、えが すこしずつ できるよ。'}</p><button class="primary start" id="back-challenge">3もんに ちょうせん →</button><p class="muted">えほんの きろくは このブラウザに のこるよ。</p></section>`;$('back-challenge').onclick=()=>{screen=session?(session.claimed?'reward':'quiz'):'setup';render();};}
$('challenge-tab').onclick=()=>{screen=session?(session.claimed?'reward':'quiz'):'setup';render();};$('album-tab').onclick=()=>{screen='album';render();};render(false);
